import csv, gzip, collections, statistics
from datetime import datetime
D = '/srv/leakruns/8dab1848f9d0-t3/ws/data/'
T = ['patients', 'admissions', 'labs', 'diagnoses', 'procedures', 'orders', 'outpatient_visits']

def load(t):
    with gzip.open(D + t + '.csv.gz', 'rt', newline='') as f:
        r = csv.DictReader(f)
        return r.fieldnames, list(r)

def infer(vals):
    v = [x for x in vals if x != '']
    if not v: return 'empty'
    def ok(fn):
        try:
            for x in v[:5000]: fn(x)
            return True
        except Exception: return False
    if ok(int): return 'int'
    if ok(float): return 'float'
    if ok(lambda x: datetime.fromisoformat(x)): return 'datetime'
    return 'str'

data = {}
for t in T:
    cols, rows = load(t)
    data[t] = rows
    print(f'\n######## {t}: rows={len(rows)} cols={cols}')
    for r in rows[:5]: print('  ', [r[c] for c in cols])
    for c in cols:
        vals = [r[c] for r in rows]
        dt = infer(vals)
        nmiss = sum(1 for x in vals if x == '')
        nu = len(set(vals))
        line = f'  - {c}: {dt}, missing={nmiss}, nunique={nu}'
        if dt in ('int', 'float') and nu > 0:
            nums = [float(x) for x in vals if x != '']
            line += f', min={min(nums)}, median={statistics.median(nums)}, max={max(nums)}'
        if dt == 'datetime':
            nn = sorted(x for x in vals if x)
            line += f', min={nn[0]}, max={nn[-1]}'
        print(line)
        if dt == 'str' or (dt == 'int' and nu <= 30):
            if nu <= 200 or dt == 'str' and nu < len(rows) * 0.5:
                vc = collections.Counter(vals).most_common(15)
                print('      top15:', vc)

import pickle
pickle.dump(data, open('/tmp/claude-0/-srv-leakruns-8dab1848f9d0-t3-ws/6aef52c4-599d-41b9-81bf-2cf90cbd2f07/scratchpad/data.pkl', 'wb'))
